def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    # Sort the numbers and remove duplicates
    nums = sorted(set(nums))

    def collapse_ranges(numbers):
        ranges =        start = end = numbers[0]

        for i in range(1, len(numbers)):
            if numbers[i] == end + 1:
                end = numbers[i]
            else:
                if end - start >= 2:
                    ranges.append(f"{start}..{end}")
                elif start == end:
                    ranges.append(str(start))
                else:
                    ranges.append(f"{start},{end}")
                start = end = numbers[i]

        # Handle the last range
        if end - start >= 2:
            ranges.append(f"{start}..{end}")
        elif start == end:
            ranges.append(str(start))
        else:
            ranges.append(f"{start},{end}")

        return ",".join(ranges)

    return collapse_ranges(nums)
