import time

class TokenBucket:
    def __init__(self, capacity: float, refill_per_sec: float, clock):
        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self.clock = clock
        self.tokens = capacity
        self.last_refill_time = clock()

    def _refill(self):
        current_time = self.clock()
        elapsed_time = current_time - self.last_refill_time
        refill_amount = elapsed_time * self.refill_per_sec
        self.tokens = min(self.capacity, self.tokens + refill_amount)
        self.last_refill_time = current_time

    def allow(self, cost: float = 1) -> bool:
        self._refill()
        if self.tokens >= cost:
            self.tokens -= cost
            return True
        return False

    @property
    def tokens(self) -> float:
        self._refill()
        return self._tokens

    @tokens.setter
    def tokens(self, value: float):
        self._tokens = value
